package com.moyer.roleplay.core

data class HelpArticle(val id: String, val title: String, val category: String, val summary: String,
    val sections: List<Pair<String, String>>, val keywords: String = "") {
    val searchableText get() = (title + summary + category + keywords + sections.joinToString { it.first + it.second }).lowercase()
}

