    fun search(query: String, category: String? = null): List<HelpArticle> {
        val terms=query.trim().lowercase().split(Regex("\\s+")).filter(String::isNotBlank)
        return articles.filter { (category==null || it.category==category) && terms.all { term -> term in it.searchableText } }
            .sortedByDescending { article -> terms.count { it in article.title.lowercase() } }
    }
}
